private static List<Invoice> notesOf(Invoice invoice, List<Invoice> all) {
    return all.stream().filter(n -> invoice.getId() != null && invoice.getId().equals(n.getAdjustmentOf())
            && !n.isDraft() && !n.isVoid()).toList();
}

